<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Katalog ShopEase</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><a href="<?= site_url('/') ?>">← Kembali ke homepage</a><h1 class="my-4">Katalog Produk</h1><form class="d-flex gap-2 mb-4"><input class="form-control" name="q" value="<?= esc($keyword ?? '') ?>" placeholder="Cari produk"><button class="btn btn-success">Cari</button></form><div class="row g-3"><?php foreach($products as $p): ?><div class="col-6 col-md-3"><div class="card h-100"><?php if($p['image']): ?><img src="<?= base_url('uploads/products/'.$p['image']) ?>" class="card-img-top" style="height:180px;object-fit:cover"><?php else: ?><div class="bg-secondary-subtle d-grid" style="height:180px;place-items:center">▧</div><?php endif; ?><div class="card-body"><b><?= esc($p['name']) ?></b><p class="text-success fw-bold">Rp<?= number_format($p['price'],0,',','.') ?></p><a href="<?= site_url('products/'.$p['slug']) ?>" class="btn btn-sm btn-outline-success">Detail</a></div></div></div><?php endforeach; ?></div><?= $pager->links() ?></div></body></html>
